const email = $input.first().json;

const KNOWLEDGE_BASE = [
  { question: "What are your hours?", answer: "We're open Monday through Friday, 9am to 5pm." },
  { question: "What is your return policy?", answer: "Items can be returned within 30 days with a receipt for a full refund." },
  { question: "How do I book a consultation?", answer: "Reply with a few times that work for you and we'll confirm a slot, or book directly at our scheduling link." },
  { question: "Do you offer refunds for cancellations?", answer: "Cancellations made more than 24 hours in advance receive a full refund." },
];

const knowledgeText = KNOWLEDGE_BASE.map(kb => `Q: ${kb.question}\nA: ${kb.answer}`).join('\n\n');

const systemPrompt = `You are drafting email replies on behalf of a small business, in a warm and professional voice.

You have the following documented answers to draw from:

${knowledgeText}

Read the customer's email below. If their question is clearly answered by the documented answers above, draft a short, natural reply grounded in that information. If it is not covered, or the request is ambiguous, unusual, or sensitive, do not guess — mark it as not confident instead.

Respond with ONLY a JSON object, no markdown formatting, no code fences, in exactly this shape:
{"draft": "<the reply text, or null if not confident>", "confident": true or false, "reason": "<one short sentence, for internal use only, explaining your decision>"}`;

const requestBody = {
  model: 'claude-sonnet-5',
  max_tokens: 1024,
  system: systemPrompt,
  messages: [
    { role: 'user', content: `Subject: ${email.subject || ''}\n\n${email.text || email.snippet || ''}` }
  ],
};

let fromAddress = '';
if (email.from) {
  if (typeof email.from === 'string') {
    const m = email.from.match(/<([^>]+)>/);
    fromAddress = m ? m[1] : email.from;
  } else if (typeof email.from === 'object') {
    fromAddress = (email.from.value && email.from.value[0] && email.from.value[0].address) || email.from.text || '';
  }
}

return [{
  json: {
    requestBody,
    original: {
      from: fromAddress,
      fromAddress,
      subject: email.subject,
      threadId: email.threadId,
      messageId: email.messageId || email.id,
    },
  },
}];

const response = $input.first().json;
const original = $('Build Prompt').item.json.original;

let text = '';
if (response.content && response.content[0] && response.content[0].text) {
  text = response.content[0].text;
}

text = text.trim();
if (text.startsWith('```')) {
  text = text.replace(/^```(json)?/i, '').replace(/```$/, '').trim();
}

let parsed;
try {
  parsed = JSON.parse(text);
} catch (e) {
  parsed = { draft: null, confident: false, reason: 'Failed to parse model response as JSON' };
}

const confident = parsed.confident === true && !!parsed.draft;

const audit = {
  source: 'inbox',
  actor: original.fromAddress || original.from || 'unknown',
  action: 'draft_reply',
  details: { subject: original.subject, modelReason: parsed.reason, draftCreated: confident },
  status: confident ? 'success' : 'escalated',
  reason: confident ? null : (parsed.reason || 'Low confidence, routed to a person'),
};

const draft = confident ? {
  subject: `Re: ${original.subject || ''}`,
  message: parsed.draft,
  sendTo: original.fromAddress || '',
  threadId: original.threadId || '',
} : null;

return [{ json: { audit, draft, confident } }];

const item = $input.first().json;
if (!item.confident || !item.draft) {
  return [];
}
return [{ json: item.draft }];
